import sys

def multiply(a, b, n):
    return (a * b) % n

def inverse(a, n):
    m = n
    r1, r2, r3, r4 = 1, 0, 0, 1
    while a > 0 and n > 0:
        if n >= a:
            r3 -= r1 * (n // a)
            r4 -= r2 * (n // a)
            n %= a
        else:
            a, n = n, a
            r1, r3 = r3, r1
            r2, r4 = r4, r2
    if a == 0:
        return r3 % m if r3 >= 0 else m + (r3 % m)
    else:
        return r1 % m if r1 >= 0 else m + (r1 % m)

def main():
    P = 998244353
    input_line = sys.stdin.readline().strip()
    n, real_k, l = map(int, input_line.split())

    factorials = [1] * (2 * n + 2)
    for i in range(1, 2 * n + 2):
        factorials[i] = multiply(factorials[i - 1], i, P)

    doublefact = [1] * (n + 1)
    for i in range(1, n + 1):
        doublefact[i] = multiply(doublefact[i - 1], (2 * i - 1), P)

    list_matrix = [[0] * (n + 1) for _ in range(2 * n + 2)]

    for r in range(1, 2 * n + 2):
        for k in range(1, n + 1):
            if ((r % 2) != (k % 2)) and (r - 1 >= k) and (2 * n + 1 - r >= k):
                num = multiply(factorials[r - 1], factorials[2 * n + 1 - r], P)
                num = multiply(num, doublefact[(r - k - 1) // 2], P)
                num = multiply(num, doublefact[(2 * n + 1 - r - k) // 2], P)

                denom = multiply(factorials[r - k - 1], factorials[2 * n + 1 - r - k], P)
                denom = multiply(denom, factorials[k], P)

                inv_denom = inverse(multiply(denom, doublefact[n], P), P)
                list_matrix[r][k] = multiply(num, inv_denom, P)

    total = 0
    for r in range(1, 2 * n + 2):
        for k in range(real_k, n + 1):
            total += list_matrix[r][k]
            total %= P

    total = multiply(total, l, P)
    total = multiply(total, inverse(2 * n + 1, P), P)

    print(total)

if __name__ == "__main__":
    main()

